Rules.InvariantScript:
With({r: Trim(varRutPd)}, If(!IsBlank(r),
    Set(varUsrTxt, IfError(Text('FolioUsuario'.Run(r).datos), Notify("No se pudo consultar FOLIO (flujo FolioUsuario): " & FirstError.Message, NotificationType.Error); ""));
    Set(varUsr, ParseJSON(If(IsBlank(varUsrTxt), "{}", varUsrTxt)));
    If(Text(varUsr.encontrado) = "SI", Set(varRutPd, Text(varUsr.rut)); Reset(txtRutPd), Notify("No está en FOLIO: puede registrar igual con el RUT escrito.", NotificationType.Warning));
    SetFocus(txtLibroPd)))

With({c: Trim(varCodLibPd)}, If(!IsBlank(c),
    Set(varLibTxt, IfError(Text('Copiade:BuscarLibroFOLIO'.Run(c).datos), Notify("No se pudo consultar FOLIO (flujo BuscarLibroFOLIO): " & FirstError.Message, NotificationType.Error); ""));
    Set(varLib, ParseJSON(If(IsBlank(varLibTxt), "{}", varLibTxt)));
    Set(varAbiertoPd, LookUp(colMov, Codigo = c && Tipo = "Préstamo" && IsBlank(Devuelto)))))

With({r: Trim(txtRutPd.Text), c: Trim(txtLibroPd.Text)},
    If(!IsEmpty(Filter(Filter(PrestamosMovimientos, Codigo = c), Tipo = "Préstamo" && IsBlank(Devuelto))), Notify("Este libro ya tiene un préstamo abierto: Registre primero la devolución.", NotificationType.Warning),
    With({mUsr: varUsr, mLib: varLib, mDias: Value(lblDiasPd.Text)}, IfError(
        Collect(colMov, With({q: Patch(PrestamosMovimientos, Defaults(PrestamosMovimientos), {Title: Text(Now(), "yyyymmddhhmmss") & "-" & Text(Rand() * 100000, "00000"), FechaHora: Text(Now(), "yyyy-mm-dd hh:mm"), Tipo: "Préstamo", RUT: r, Correo: Coalesce(Text(varUsr.correo), Text(varUsr.email), ""), Usuario: Coalesce(Text(varUsr.nombre), ""), Codigo: c, Titulo: Coalesce(Text(varLib.titulo), ""), Biblioteca: Coalesce(varYo.Biblioteca, ""), Vence: Text(DateAdd(Today(), Value(lblDiasPd.Text), TimeUnit.Days), "yyyy-mm-dd"), Devuelto: "", Atraso: "", RegistradoPor: Coalesce(varYo.Nombre, User().FullName), CargadoAlma: "No", Obs: ""})}, {Id: q.Title, FechaHora: q.FechaHora, Tipo: q.Tipo, RUT: q.RUT, Usuario: q.Usuario, Codigo: q.Codigo, Titulo: q.Titulo, Biblioteca: q.Biblioteca, Vence: q.Vence, Devuelto: q.Devuelto, Atraso: q.Atraso, RegistradoPor: q.RegistradoPor, CargadoAlma: q.CargadoAlma, Obs: q.Obs, SPID: q.ID}));
        Notify("Préstamo registrado · vence " & Text(DateAdd(Today(), Value(lblDiasPd.Text), TimeUnit.Days), "dd-mm-yyyy"), NotificationType.Success);
        Set(varRutPd, ""); Set(varCodLibPd, ""); Reset(txtRutPd); Reset(txtLibroPd); Set(varUsr, ParseJSON("{}")); Set(varLib, ParseJSON("{}")); Set(varAbiertoPd, Blank()); SetFocus(txtRutPd);
        With({para: Coalesce(Text(mUsr.correo), Text(mUsr.email), "")}, If(IsBlank(para), Notify("Préstamo guardado. El usuario no tiene correo en FOLIO: No se envió comprobante.", NotificationType.Warning), IfError(Office365Outlook.SendEmailV2(para, "Bibliotecas UAI · Comprobante de préstamo", "<div style='font-family:Open Sans,Segoe UI,Arial,sans-serif;color:#111111;font-size:13px;max-width:720px'><div style='background:#111111;color:#FFFFFF;padding:14px 18px'><div style='font-size:10px;letter-spacing:3px;color:#BFC3C8'>BIBLIOTECAS UAI</div><div style='font-size:17px;font-weight:700;margin-top:3px'>Comprobante de préstamo</div></div><p>Estimado/a " & Substitute(Substitute(Coalesce(Text(mUsr.nombre), "usuario/a"), "&", "&amp;"), "<", "&lt;") & ":</p><p>Le confirmamos el siguiente préstamo registrado a su nombre:</p><table style='border-collapse:collapse;width:720px;max-width:100%'><tr><th style='background:#111111;color:#FFFFFF;font-weight:700;font-size:12px;padding:10px 8px;text-align:left'>Título</th><th style='background:#111111;color:#FFFFFF;font-weight:700;font-size:12px;padding:10px 8px;text-align:center'>Código</th><th style='background:#111111;color:#FFFFFF;font-weight:700;font-size:12px;padding:10px 8px;text-align:left'>Biblioteca</th><th style='background:#111111;color:#FFFFFF;font-weight:700;font-size:12px;padding:10px 8px;text-align:center'>Fecha de préstamo</th><th style='background:#111111;color:#FFFFFF;font-weight:700;font-size:12px;padding:10px 8px;text-align:center'>Devolver hasta</th></tr><tr><td style='padding:10px 8px;border-bottom:1px solid #DADCDF;font-size:12px'>" & Substitute(Substitute(Coalesce(Text(mLib.titulo), "Sin título"), "&", "&amp;"), "<", "&lt;") & "</td><td style='padding:10px 8px;border-bottom:1px solid #DADCDF;font-size:12px;text-align:center'>" & c & "</td><td style='padding:10px 8px;border-bottom:1px solid #DADCDF;font-size:12px'>" & Coalesce(varYo.Biblioteca, "Bibliotecas UAI") & "</td><td style='padding:10px 8px;border-bottom:1px solid #DADCDF;font-size:12px;text-align:center;white-space:nowrap'>" & Text(Today(), "dd-mm-yyyy") & "</td><td style='padding:10px 8px;border-bottom:1px solid #DADCDF;font-size:12px;text-align:center;white-space:nowrap'><b>" & Text(DateAdd(Today(), mDias, TimeUnit.Days), "dd-mm-yyyy") & "</b></td></tr></table><p>Puede devolverlo en cualquiera de nuestras bibliotecas. Recuerde que los atrasos pueden restringir sus próximos préstamos.</p><p>Atentamente,<br>Bibliotecas UAI</p></div>"), Notify("Préstamo guardado, pero no se pudo enviar el correo: " & FirstError.Message, NotificationType.Warning)))),
        Notify("No se pudo guardar: " & FirstError.Message, NotificationType.Error)))))

With({c: Trim(txtLibroPd.Text), p: varAbiertoPd},
    IfError(
        If(!IsBlank(p),
            With({atr: Max(0, DateDiff(IfError(DateValue(p.Vence), Today()), Today(), TimeUnit.Days))},
                Patch(PrestamosMovimientos, LookUp(PrestamosMovimientos, Title = p.Id), {Devuelto: Text(Now(), "yyyy-mm-dd hh:mm"), Atraso: Text(atr)}); Patch(colMov, p, {Devuelto: Text(Now(), "yyyy-mm-dd hh:mm"), Atraso: Text(atr)})));
        Collect(colMov, With({q: Patch(PrestamosMovimientos, Defaults(PrestamosMovimientos), {Title: Text(Now(), "yyyymmddhhmmss") & "-" & Text(Rand() * 100000, "00000"), FechaHora: Text(Now(), "yyyy-mm-dd hh:mm"), Tipo: "Devolución", RUT: Coalesce(p.RUT, ""), Usuario: Coalesce(p.Usuario, ""), Codigo: c, Titulo: Coalesce(p.Titulo, Text(varLib.titulo), ""), Biblioteca: Coalesce(varYo.Biblioteca, ""), Vence: Coalesce(p.Vence, ""), Devuelto: Text(Now(), "yyyy-mm-dd hh:mm"), Atraso: If(IsBlank(p), "", Text(Max(0, DateDiff(IfError(DateValue(p.Vence), Today()), Today(), TimeUnit.Days)))), RegistradoPor: Coalesce(varYo.Nombre, User().FullName), CargadoAlma: "No", Obs: If(IsBlank(p), "Préstamo hecho antes de la contingencia", "")})}, {Id: q.Title, FechaHora: q.FechaHora, Tipo: q.Tipo, RUT: q.RUT, Usuario: q.Usuario, Codigo: q.Codigo, Titulo: q.Titulo, Biblioteca: q.Biblioteca, Vence: q.Vence, Devuelto: q.Devuelto, Atraso: q.Atraso, RegistradoPor: q.RegistradoPor, CargadoAlma: q.CargadoAlma, Obs: q.Obs, SPID: q.ID}));
        Notify(If(!IsBlank(p) && IfError(DateValue(p.Vence), Today()) < Today(), "Devolución registrada con atraso de " & DateDiff(IfError(DateValue(p.Vence), Today()), Today(), TimeUnit.Days) & " días", "Devolución registrada"), If(!IsBlank(p) && IfError(DateValue(p.Vence), Today()) < Today(), NotificationType.Warning, NotificationType.Success));
        Set(varCodLibPd, ""); Reset(txtLibroPd); Set(varLib, ParseJSON("{}")); Set(varAbiertoPd, Blank()); SetFocus(txtLibroPd),
        Notify("No se pudo guardar: " & FirstError.Message, NotificationType.Error)))
